<?php
session_start();
// Ajuste estas credenciais se necessário (padrão XAMPP).
const DB_HOST='localhost'; const DB_USER='root'; const DB_PASS=''; const DB_NAME='cmd';
$pdo=null; $dbErro='';
try {
  $server=new PDO('mysql:host='.DB_HOST.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
  $server->exec('CREATE DATABASE IF NOT EXISTS `'.DB_NAME.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');
  $pdo=new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
  $pdo->exec("CREATE TABLE IF NOT EXISTS microempreendedores(id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE,senha VARCHAR(255) NOT NULL,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
  $pdo->exec("CREATE TABLE IF NOT EXISTS produtos(id INT AUTO_INCREMENT PRIMARY KEY,microempreendedor_id INT NOT NULL,nome VARCHAR(160) NOT NULL,preco DECIMAL(10,2) NOT NULL,whatsapp VARCHAR(30) NULL,instagram VARCHAR(120) NULL,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(microempreendedor_id) REFERENCES microempreendedores(id) ON DELETE CASCADE) ENGINE=InnoDB");
} catch(PDOException $e){$dbErro='Não foi possível conectar ao banco. Confira se o MySQL está ligado e as credenciais no início do arquivo.';}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function voltar($tipo,$msg){$_SESSION['flash']=['tipo'=>$tipo,'msg'=>$msg];header('Location: '.strtok($_SERVER['REQUEST_URI'],'?'));exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && $pdo){
 $acao=$_POST['acao']??'';
 if($acao==='criar_conta'){
  $nome=trim($_POST['nome']??'');$email=trim($_POST['email']??'');$senha=$_POST['senha']??'';
  if($nome===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($senha)<6)voltar('erro','Preencha os campos corretamente. A senha deve ter pelo menos 6 caracteres.');
  try{$st=$pdo->prepare('INSERT INTO microempreendedores(nome,email,senha) VALUES(?,?,?)');$st->execute([$nome,$email,password_hash($senha,PASSWORD_DEFAULT)]);voltar('sucesso','Conta criada! Agora você já pode entrar.');}
  catch(PDOException $e){if($e->getCode()==='23000')voltar('erro','Este e-mail já está cadastrado.');voltar('erro','Não foi possível criar a conta.');}
 }
 if($acao==='login'){
  $st=$pdo->prepare('SELECT id,nome,email,senha FROM microempreendedores WHERE email=? LIMIT 1');$st->execute([trim($_POST['email']??'')]);$u=$st->fetch();
  if($u&&password_verify($_POST['senha']??'',$u['senha'])){session_regenerate_id(true);$_SESSION['usuario']=['id'=>$u['id'],'nome'=>$u['nome'],'email'=>$u['email']];voltar('sucesso','Login realizado com sucesso!');}
  voltar('erro','E-mail ou senha incorretos.');
 }
 if($acao==='cadastrar_produto'){
  if(empty($_SESSION['usuario']['id']))voltar('erro','Entre na sua conta para cadastrar produtos.');
  $nome=trim($_POST['nome_produto']??'');$preco=str_replace(',','.',trim($_POST['preco']??''));$w=preg_replace('/\D+/','',$_POST['whatsapp']??'');$ig=trim($_POST['instagram']??'');
  $wOk=$w!==''&&strlen($w)>=10&&strlen($w)<=13;$igOk=$ig!==''&&preg_match('/^(https?:\/\/)?(www\.)?instagram\.com\/[A-Za-z0-9._]+\/?$|^@?[A-Za-z0-9._]{1,30}$/i',$ig);
  if($nome===''||!is_numeric($preco)||(float)$preco<=0||(!$wOk&&!$igOk))voltar('erro','Informe nome, preço válido e pelo menos um contato válido (WhatsApp ou Instagram).');
  $st=$pdo->prepare('INSERT INTO produtos(microempreendedor_id,nome,preco,whatsapp,instagram) VALUES(?,?,?,?,?)');$st->execute([$_SESSION['usuario']['id'],$nome,number_format((float)$preco,2,'.',''),$wOk?$w:null,$igOk?ltrim($ig,'@'):null]);voltar('sucesso','Produto cadastrado e publicado no catálogo!');
 }
 if($acao==='logout'){unset($_SESSION['usuario']);session_regenerate_id(true);voltar('sucesso','Você saiu da sua conta.');}
}
$produtos=[];if($pdo){$produtos=$pdo->query('SELECT p.*,m.nome AS vendedor FROM produtos p INNER JOIN microempreendedores m ON m.id=p.microempreendedor_id ORDER BY p.criado_em DESC')->fetchAll();}
$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);$logado=!empty($_SESSION['usuario']);$nomeUsuario=$_SESSION['usuario']['nome']??'';
?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>CMD | Catálogo de Marketing Digital</title>
<style>
