gn-items:end;gap:20px;margin-bottom:30px}.eyebrow{color:var(--blue);font-size:12px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase}h1{margin:8px 0 9px;font-size:clamp(27px,3vw,36px);letter-spacing:-.9px}.desc{margin:0;color:var(--muted);font-size:15px;line-height:1.6}.count{padding:9px 13px;border-radius:30px;color:#3976a9;background:var(--pale);font-size:12px;font-weight:700;white-space:nowrap}.empty{min-height:330px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:35px 20px;border:1px dashed #c9dced;border-radius:18px;background:linear-gradient(180deg,#fbfdff,#f5faff)}.empty-icon{width:88px;height:88px;display:grid;place-items:center;margin-bottom:21px;border-radius:26px;color:var(--blue);background:#e5f3ff}.empty-icon svg{width:45px;height:45px}.empty h2{margin:0 0 9px;font-size:21px}.empty p{max-width:440px;margin:0;color:var(--muted);line-height:1.6;font-size:14px}.empty .blue{margin-top:22px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(215px,1fr));gap:20px}.product{overflow:hidden;border:1px solid var(--line);border-radius:16px;background:white;transition:.2s}.product:hover{transform:translateY(-4px);box-shadow:0 12px 28px #164b741a}.product-art{height:145px;display:grid;place-items:center;color:#6aa9d9;background:linear-gradient(135deg,#eaf6ff,#f8fbff)}.product-art svg{width:48px;height:48px}.product-info{padding:17px}.product-info h3{margin:0 0 9px;font-size:17px}.price{color:#087bca;font-size:20px;font-weight:800}.seller{margin:9px 0 13px;color:var(--muted);font-size:12px}.contacts{display:flex;flex-wrap:wrap;gap:8px}.contacts a{padding:8px 10px;border-radius:8px;color:#08764c;background:#e8f8f0;text-decoration:none;font-size:12px;font-weight:700}.contacts a.ig{color:#9c356b;background:#fff0f6}.footer{padding:25px 10px 0;color:#ffffffd9;text-align:center;font-size:12px}.notice{width:min(1180px,100%);margin:-28px auto 25px;padding:13px 16px;border-radius:10px;font-size:14px}.success{color:#17633e;background:#e7f8ef;border:1px solid #c6efd8}.error{color:#963b36;background:#fff0ef;border:1px solid #ffd3d0}.db-warning{width:min(1180px,100%);margin:-25px auto 25px;padding:13px 16px;border-radius:10px;color:#80531b;background:#fff8e8;font-size:13px}.modal{position:fixed;inset:0;z-index:20;display:none;align-items:center;justify-content:center;padding:20px;background:#0a1e5299;backdrop-filter:blur(5px)}.modal.open{display:flex}.modal-box{position:relative;width:min(460px,100%);max-height:92vh;overflow-y:auto;padding:34px;border-radius:21px;background:white;box-shadow:0 25px 80px #0003;animation:pop .22s ease-out}@keyframes pop{from{opacity:0;transform:translateY(12px) scale(.98)}to{opacity:1;transform:none}}.close{position:absolute;top:15px;right:17px;width:34px;height:34px;border:0;border-radius:50%;color:#62758a;background:#f1f5f9;font-size:22px}.modal-icon{width:48px;height:48px;display:grid;place-items:center;margin-bottom:17px;border-radius:14px;color:var(--blue);background:var(--pale)}.modal-icon svg{width:25px;height:25px}.modal-box h2{margin:0 35px 8px 0;font-size:24px}.modal-sub{margin:0 0 23px;color:var(--muted);font-size:13px;line-height:1.55}.field{margin-bottom:16px}.field label{display:block;margin-bottom:7px;color:#35485c;font-size:13px;font-weight:700}.field input{width:100%;height:46px;padding:0 13px;outline:none;border:1px solid #dce5ee;border-radius:10px;color:var(--ink);background:#fbfdff;transition:.2s}.field input:focus{border-color:#53a8e8;box-shadow:0 0 0 3px #0878d11a;background:white}.field small{display:block;margin-top:6px;color:#8291a1;font-size:11px;line-height:1.4}.modal-box .blue{width:100%;margin-top:5px}.switch{margin:19px 0 0;color:var(--muted);text-align:center;font-size:13px}.switch button{border:0;padding:0;color:var(--blue);background:none;font-weight:750}.contact-divider{margin:19px 0;border:0;border-top:1px solid var(--line)}
@media(max-width:700px){.page{padding:18px 16px 35px}.top{margin-bottom:28px}.brand-mark{width:42px;height:42px}.brand-name{font-size:24px}.brand-sub{font-size:9px}.actions{gap:13px}.primary{padding:12px 13px;font-size:12px}.login-link{font-size:13px}.user{gap:7px;font-size:12px}.panel{padding:25px 18px;min-height:470px;border-radius:19px}.panel-head{align-items:start;flex-direction:column}.empty{min-height:290px}.modal-box{padding:28px 22px}}@media(max-width:390px){.brand-sub{display:none}.actions{gap:9px}.primary{padding:11px 10px}}
